// word-ladder/js/engine.js - PURE: the words, the levels, a move, the hint, the stars. No DOM, no storage.
//
// A level = { s: start, t: target, p: par (fewest changes, the shortest path over EVERY accepted word), h: one
// shortest path "S W1 ... T" }. Data is GENERATED by tools/build-word-ladder-data.mjs (never hand-edited).
// A move = change ONE letter of the current word; the new word must be on the accepted list. Every move counts,
// undo included (it is a move back), so par is the target for "Moves".

export const BANDS = [
  // [tier, first level]; a level's band = the last whose first level is <= it (stats byDiff bucket).
  ['easy', 1], ['medium', 101], ['hard', 251], ['expert', 401],
];
export const LAST_LEVEL = 500;
/** [first, last] level of a band (each difficulty is its own run of levels, played in order). */
export function bandRange(band) {
  const i = BANDS.findIndex(([t]) => t === band);
  if (i < 0) return [1, LAST_LEVEL];
  return [BANDS[i][1], i + 1 < BANDS.length ? BANDS[i + 1][1] - 1 : LAST_LEVEL];
}
export const TIERS = ['easy', 'medium', 'hard', 'expert'];
export function bandOf(n) {
  let b = 'easy';
  for (const [tier, first] of BANDS) if (n >= first) b = tier;
  return b;
}

/** Stars for a finished ladder: moves at par = 3, up to 2 over = 2, else 1; 1 hint caps at 2, 2+ hints at 1. */
export function starsFor(moves, par, hints = 0) {
  const m = Math.max(0, moves | 0), p = Math.max(1, par | 0), h = Math.max(0, hints | 0);
  const byMoves = m <= p ? 3 : m <= p + 2 ? 2 : 1;
  const byHints = h === 0 ? 3 : h === 1 ? 2 : 1;
  return Math.min(byMoves, byHints);
}

export const ALPHABET = { en: 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', es: 'ABCDEFGHIJKLMNÑOPQRSTUVWXYZ' };

/** A dictionary from words.json: { has(w), order(w) (lower = grid word / more common), list(len) }. */
export function makeDict(json) {
  const order = new Map();
  const lists = {};
  const w = (json && json.w) || {};
  for (const k of Object.keys(w)) {
    lists[k] = String(w[k] || '').split(' ').filter(Boolean);
    lists[k].forEach((word, i) => order.set(word, i));
  }
  return {
    has: (x) => order.has(x),
    order: (x) => (order.has(x) ? order.get(x) : Infinity),
    list: (len) => lists[String(len)] || [],
  };
}

/** Words one letter away from `w` that are in the dictionary. */
export function neighbours(dict, w, alphabet) {
  const out = [];
  for (let i = 0; i < w.length; i++) for (const ch of alphabet) {
    if (ch === w[i]) continue;
    const x = w.slice(0, i) + ch + w.slice(i + 1);
    if (dict.has(x)) out.push(x);
  }
  return out;
}

/** Changes between two equal-length words (position by position). */
export function diffCount(a, b) {
  if (a.length !== b.length) return Infinity;
  let n = 0;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) n++;
  return n;
}

/** Is `next` a legal move from `cur`: same length, exactly one letter changed, a word? Returns 'ok' or why not. */
export function checkMove(dict, cur, next) {
  if (!next || next.length !== cur.length) return 'len';
  const d = diffCount(cur, next);
  if (d === 0) return 'same';
  if (d !== 1) return 'two';
  return dict.has(next) ? 'ok' : 'word';
}

/** Distances to `target` over the dictionary (BFS), as a Map. */
export function distancesTo(dict, target, alphabet) {
  const d = new Map([[target, 0]]);
  const q = [target];
  for (let i = 0; i < q.length; i++) for (const n of neighbours(dict, q[i], alphabet)) if (!d.has(n)) { d.set(n, d.get(q[i]) + 1); q.push(n); }
  return d;
}

/** The hint from `cur`: the next word on a shortest path to `target`, preferring the commonest (dictionary order);
 *  null when `cur` is the target or no path exists. */
export function hintFrom(dict, cur, target, alphabet, dist = distancesTo(dict, target, alphabet)) {
  if (cur === target || !dist.has(cur)) return null;
  const want = dist.get(cur) - 1;
  let best = null;
  for (const n of neighbours(dict, cur, alphabet)) if (dist.get(n) === want && (!best || dict.order(n) < dict.order(best))) best = n;
  return best;
}

/** A level as loaded, or null when it does not add up (never drawn wrong). */
export function cleanLevel(l) {
  if (!l || typeof l !== 'object') return null;
  const s = String(l.s || ''), t = String(l.t || ''), p = Math.floor(Number(l.p) || 0);
  const h = String(l.h || '').split(' ').filter(Boolean);
  if (!s || s.length !== t.length || p < 1 || h.length !== p + 1 || h[0] !== s || h[h.length - 1] !== t) return null;
  return { s, t, p, h };
}

/** A saved attempt, read back safely: { chain: [words...], moves, hints, done, recorded }. The chain always starts at
 *  the level's start; a word that is not a legal step from the one before ends it there. Never throws. */
export function cleanAttempt(a, level, dict) {
  // A save made on a DIFFERENT puzzle (its first word is not this level's start: the data was remade under that
  // number or day) is not this attempt: none of its moves or hints count here (2026-11-13: Matt's daily read 5 moves
  // for a 4-move ladder, one move carried over from the old LIES puzzle).
  if (a && Array.isArray(a.chain) && a.chain.length && String(a.chain[0]) !== level.s) a = null;
  if (a && a.s && String(a.s) !== level.s) a = null;
  // A finished, RECORDED attempt is kept as saved even if a word has since left the list (it was legal when played).
  if (a && a.done && a.recorded && Array.isArray(a.chain) && a.chain[a.chain.length - 1] === level.t && a.chain.length >= 2) {
    const n0 = (v) => Math.max(0, Math.floor(Number(v) || 0));
    return { chain: a.chain.map(String), moves: Math.max(n0(a.moves), a.chain.length - 1), hints: n0(a.hints), done: true, recorded: true };
  }
  const chain = [level.s];
  try {
    const c = Array.isArray(a && a.chain) ? a.chain : [];
    for (let i = 1; i < c.length; i++) {
      const w = String(c[i] || '');
      if (checkMove(dict, chain[chain.length - 1], w) !== 'ok') break;
      chain.push(w);
    }
  } catch { /* keep what was read */ }
  const n = (v) => Math.max(0, Math.floor(Number(v) || 0));
  const moves = Math.max(n(a && a.moves), chain.length - 1);
  return { chain, moves, hints: n(a && a.hints), done: chain[chain.length - 1] === level.t, recorded: !!(a && a.recorded) };
}

/** The chain shown: an undo takes the last word off (the move still counts). */
export function undoChain(chain) {
  return chain.length > 1 ? chain.slice(0, -1) : chain;
}
